import csv
import io


def read_records(text):
    rows = csv.reader(io.StringIO(text, newline=""))

    header = next((row for row in rows if row != []), None)
    if header is None:
        return []

    header = [name.strip() for name in header]
    if any(name == "" for name in header):
        raise ValueError("header names must not be empty")
    if len(set(header)) != len(header):
        raise ValueError("header names must be unique")

    records = []
    for row in rows:
        if row == []:
            continue
        if len(row) != len(header):
            raise ValueError("data row has a different field count than the header")
        records.append(dict(zip(header, row)))
    return records

